document.addEventListener('submit',event=>{const f=event.target;if(!(f instanceof HTMLFormElement))return;event.preventDefault();
 if(f.id==='reminder-form'){advance.makeReminder(f);return;}
 if(f.id==='checkin-form'){saveCheckin(f);return;}
 if(f.id==='preferences-form'){let fd=new FormData(f);store.preferences={...store.preferences,...advance.comfortValues(fd),role:String(fd.get('role')),time:+fd.get('time'),style:String(fd.get('style')),motion:fd.has('motion'),visual3d:fd.has('visual3d'),hideQuotes:!fd.has('quotes')};state.budget=store.preferences.time;state.style=store.preferences.style;persist();applyPrefs();closeModal();render();toast('Your preferences are saved in this browser.');return;}
 if(f.id==='journal-form'){let text=$('#journal-draft').value.trim();if(!text){toast('Write a thought first, however small.');$('#journal-draft').focus();return;}let fd=new FormData(f),persistent=fd.has('persist');store.journals.push({id:uid(),date:new Date().toISOString(),text,persistent});clearDraft();persist();render();toast(persistent?'Reflection saved in this browser.':'Reflection kept for this visit only.');return;}
 if(f.id==='edit-journal-form'){let x=store.journals.find(x=>x.id===state.editing),text=String(new FormData(f).get('text')).trim();if(!text){toast('A reflection needs at least a few words.');return;}x.text=text;persist();closeModal();render();toast('Reflection updated.');return;}
 if(f.id==='routine-form'){let selected=new FormData(f).getAll('practice');if(!selected.length||selected.length>4){$('#routine-error').textContent='Choose one to four practices.';return;}store.routine=[...store.routine.filter(x=>selected.includes(x)),...selected.filter(x=>!store.routine.includes(x))];persist();closeModal();state.spaceTab='routine';navigate('space');toast('Your routine is ready.');return;}
 if(f.id==='work-form'){let fd=new FormData(f),v=[0,1,2].map(i=>String(fd.get('field'+i)).trim());if(v.some(x=>!x))return;$('#work-output').value=f.dataset.mode==='conversation'?`I would like to discuss this situation: ${v[0]}.\n\nThe support that would help is: ${v[1]}.\n\nCould we agree this next step: ${v[2]}?`:`Before leaving: ${v[0]}.\n\nMy transition: ${v[1]}.\n\nMy recovery support: ${v[2]}.`;$('#copy-note').textContent='Draft ready. Edit the words so they sound like you.';}
});
